<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserAcceptedTermnsOfUse\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserAcceptedTermnsOfUse\Domain\ValueObject\UserAcceptedTermnsOfUseConditionsVO;
use Civi\Lughauth\Features\Access\TenantTermsOfUse\Domain\TenantTermsOfUseRef;

trait UserAcceptedTermnsOfUseConditionsAttributeHolder
{
    protected UserAcceptedTermnsOfUseConditionsVO|TenantTermsOfUseRef|null $conditions = null;
    protected bool $conditionsAssigned = false;

    public function getConditionsOrCurrent(UserAcceptedTermnsOfUseConditionsVO $conditions): UserAcceptedTermnsOfUseConditionsVO
    {
        if ($this->conditionsAssigned) {
            \assert(null !== $this->conditions);
            return UserAcceptedTermnsOfUseConditionsVO::from($this->conditions);
        } else {
            return $conditions;
        }
    }
    public function conditionsTryBuildInitial(ConstraintFailList $error): ?UserAcceptedTermnsOfUseConditionsVO
    {
        return  UserAcceptedTermnsOfUseConditionsVO::tryFrom($this->conditionsAssigned ? $this->conditions : null, $error);
    }
    public function conditions(UserAcceptedTermnsOfUseConditionsVO|TenantTermsOfUseRef $conditions): static
    {
        $this->conditions = $conditions;
        $this->conditionsAssigned = true;
        return $this;
    }
    public function getConditions(): ?TenantTermsOfUseRef
    {
        return $this->conditions instanceof UserAcceptedTermnsOfUseConditionsVO ? $this->conditions->value() : $this->conditions;
    }
    public function isConditionsAssigned(): bool
    {
        return $this->conditionsAssigned;
    }
    public function writeConditionsTo(mixed $att): void
    {
        if ($this->conditionsAssigned) {
            \assert(null !== $this->conditions);
            $att->conditions($this->conditions);
        }
    }
    public function readConditionsFrom(mixed $att): void
    {
        if ($att->isConditionsAssigned()) {
            $conditions = $att->getConditions();
            \assert(null !== $conditions);
            $this->conditions($conditions);
        }
    }
    public function unsetConditions(): static
    {
        $this->conditionsAssigned = false;
        return $this;
    }
    protected function withDefaultConditions(): void
    {
    }
    protected function withAssertedConditionsRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->conditionsAssigned = $this->conditionsAssigned) {
            $value->conditions = UserAcceptedTermnsOfUseConditionsVO::tryFrom($this->conditions, $errorsList);
        }
    }
}
